#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/worktrees_page.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="The HTML detail page of git:worktree:list"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# The HTML page of git:worktree:list. write_worktrees_page gets the rows, the
# attention entries and the time text, and writes the page.
#
# A row is a dict with one key for each column: kind, repo, the r_* keys of a
# repo row (r_role, r_host, r_glyph, r_default, r_fetched, r_pinned, r_note,
# r_fix) and the w_* keys of a worktree or branch row (w_branch, w_detached,
# w_commit, w_age, w_base, w_ba, w_bb, w_pa, w_pb, w_origin, w_oa, w_ob,
# w_sync, w_conflict, w_dirty, w_dglyph, w_codes, w_op, w_locked, w_missing,
# w_stash, w_merged, w_notpin, w_default, w_path). An attention entry is a dict with the
# keys a_rank, a_glyph, a_color, a_repo, a_branch, a_msg and a_cmd. A missing
# key is an empty value.

import os
import tempfile

# The glyphs are UTF-8 text: most are Nerd Font private-use codepoints, and an
# editor or a copy can lose them without a message. The host, folder, tree,
# branch, up and mixed glyphs have the same codepoints as the claude-status repo.
G_GITHUB = ""
G_GITLAB = "\U000f0ba0"
G_REMOTE = ""
G_GIT = ""
G_FOLDER = ""
G_TREE = "\U0001f332"
G_BRANCH = ""
G_UP = "↑"
G_DOWN = "↓"
G_MIX = "±"
G_OK = "✓"
G_SYNC = "≡"
G_DRIFT = "≠"
G_WARN = ""
G_LOCK = "\U0001f512"
G_DETACHED = "⌀"
G_MERGED = ""
G_UNMERGED = "○"
G_STASH = ""
G_OP = "⟳"
G_GONE = "\U000f0164"
G_LOCAL = ""
G_NOFOLDER = "\U000f19f9"
G_FETCH = ""
G_PIN = "\U0001f4cc"
G_NA = "·"
G_DEFAULT = "★"

# One legend for the table and for the page: "<section>|<glyph> <text>|...".
LEGEND = (
  (
    f"Row|{G_FOLDER} main worktree|{G_TREE} linked worktree|{G_BRANCH} branch, no worktree|{G_DETACHED} detached"
    f"|{G_DEFAULT} default branch (origin/HEAD)"
  ),
  (
    f"Base, origin|{G_OK} level|{G_UP} ahead|{G_DOWN} behind|{G_GONE} upstream gone|{G_LOCAL} local only"
    f"|{G_NA} not applicable"
  ),
  f"Sync|{G_SYNC} has the main HEAD|{G_DRIFT} drifted",
  (
    f"State|{G_OK} clean|+ files added|- files deleted|{G_MIX} files mixed|{G_WARN} conflict"
    f"|{G_OP} rebase or merge stopped"
  ),
  f"|{G_LOCK} locked|{G_NOFOLDER} folder missing|{G_STASH} stash|{G_PIN} not at pin",
  (
    f"Merged|{G_MERGED} main, develop or both: each commit is in that branch"
    f"|{G_UNMERGED} in neither|{G_NA} nothing to compare"
  ),
  f"Repo|{G_GITHUB} GitHub|{G_GITLAB} GitLab|{G_REMOTE} other remote|{G_GIT} no origin|{G_FETCH} not on disk",
)

# The page has its own small font: a subset of FiraCode Nerd Font with only the
# glyphs of the task. Thus it renders without a Nerd Font on the machine.
WORKTREES_FONT = ""

PAGE_STYLES = """\
:root{color-scheme:light dark;--bg:#fff;--fg:#1f2328;--dim:#656d76;--line:#d0d7de;--band:#f6f8fa;--ok:#1a7f37;--warn:#9a6700;--bad:#cf222e}
@media(prefers-color-scheme:dark){:root{--bg:#0d1117;--fg:#e6edf3;--dim:#8b949e;--line:#30363d;--band:#161b22;--ok:#3fb950;--warn:#d29922;--bad:#f85149}}
*{box-sizing:border-box}body{margin:0 auto;max-width:1500px;padding:32px 24px 56px;background:var(--bg);color:var(--fg);font:16px/1.55 -apple-system,system-ui,sans-serif}
h1{font-size:28px;margin:0}h2{font-size:21px;margin:40px 0 12px}.sub{color:var(--dim);margin:4px 0 24px}
code,td.m{font-family:ui-monospace,Menlo,Consolas,monospace}.g{font-family:Glyphs,ui-monospace,Menlo,monospace;font-size:17px;white-space:nowrap}
.green{color:var(--ok)}.yellow{color:var(--warn)}.red{color:var(--bad)}.dim{color:var(--dim)}
.tiles{display:flex;flex-wrap:wrap;gap:12px}.tile{border:1px solid var(--line);border-radius:8px;padding:12px 18px;min-width:150px}.tile b{display:block;font-size:28px;line-height:1.2}.tile span{color:var(--dim);font-size:15px}
.scroll{overflow-x:auto;border:1px solid var(--line);border-radius:8px}table{border-collapse:collapse;width:100%}th,td{padding:8px 14px;text-align:left;white-space:nowrap;font-size:16px}
th{color:var(--dim);font-weight:600;border-bottom:1px solid var(--line)}td.m{font-size:15px}
tr.repo td{background:var(--band);border-top:1px solid var(--line);font-weight:600;font-size:17px}tr.repo .g{margin-right:8px}tr.repo span.i{font-weight:400;font-size:15px;color:var(--dim);margin-left:10px}
.ref{color:var(--dim);font-family:ui-monospace,Menlo,monospace;font-size:14.5px}
.legend{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}.legend section{border:1px solid var(--line);border-radius:8px;padding:14px 18px}.legend section.wide{grid-column:span 2}
.legend h3{font-size:15px;font-weight:600;color:var(--dim);margin:0 0 10px}.legend ul{list-style:none;margin:0;padding:0;display:grid;gap:7px 20px}.legend .wide ul{grid-template-columns:1fr 1fr}
.legend li{display:grid;grid-template-columns:30px 1fr;align-items:baseline}.legend li .g{font-size:19px}
@media(max-width:640px){.legend section.wide{grid-column:auto}.legend .wide ul{grid-template-columns:1fr}}
footer{color:var(--dim);font-size:15px;margin-top:32px}
"""


def _v(row, key):
  """The value of key in row as text; an empty text when the key is missing."""
  value = row.get(key)
  return "" if value is None else str(value)


def _n(row, key):
  """The value of key in row as a number, as bash arithmetic reads it: an empty
  value is 0."""
  value = _v(row, key).strip()
  try:
    return int(value) if value else 0
  except ValueError:
    return 0


def count_cell(ahead, behind):
  """The cell and its color of the counts ahead and behind, as (cell, color)."""
  ahead = "" if ahead is None else str(ahead)
  behind = "" if behind is None else str(behind)
  cell = ""
  color = ""
  if not ahead:
    cell, color = G_NA, "dim"
  elif ahead == "0" and behind == "0":
    cell, color = G_OK, "green"
  else:
    if ahead != "0":
      cell = f"{G_UP}{ahead}"
    if behind != "0":
      cell = f"{cell} {G_DOWN}{behind}" if cell else f"{G_DOWN}{behind}"
      color = "yellow"
  return cell, color


def merged_cell(row):
  """The merged cell of the row and its color, as (cell, color): the local main
  or develop, or both, that has each commit of the row."""
  merged = _v(row, "w_merged")
  if merged == "no":
    return G_UNMERGED, "yellow"
  if not merged:
    return G_NA, "dim"
  return f"{G_MERGED} {merged}", "green"


def state_parts(row):
  """The state parts of the row, as a list of (glyph, color, word). The page and
  the JSON use the same parts. A row without a worktree has no parts."""
  parts = []
  if _v(row, "kind") == "branch":
    pass
  elif _v(row, "w_missing"):
    parts.append((G_NOFOLDER, "red", "folder missing"))
  else:
    conflict = _n(row, "w_conflict")
    dirty = _n(row, "w_dirty")
    if _v(row, "w_notpin"):
      parts.append((G_PIN, "yellow", "not at the pinned commit"))
    if _v(row, "w_locked"):
      parts.append((G_LOCK, "yellow", "locked"))
    if conflict > 0:
      parts.append((f"{G_WARN}{_v(row, 'w_conflict')}", "red", f"conflict: U{_v(row, 'w_conflict')}"))
    if dirty > 0:
      parts.append((f"{_v(row, 'w_dglyph')}{_v(row, 'w_dirty')}", "yellow", f"dirty: {_v(row, 'w_codes')}"))
    if _v(row, "w_op"):
      parts.append((G_OP, "red", f"{_v(row, 'w_op')} stopped"))
    if conflict == 0 and dirty == 0 and not _v(row, "w_op"):
      parts.append((G_OK, "green", "clean"))
  return parts


def html_escape(s):
  """s with the HTML characters escaped."""
  return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")


def page_glyph(text, color="", title=""):
  """A glyph span with the color class color and the title title."""
  if title:
    t = html_escape(title)
    return f'<span class="g {color}" title="{t}" aria-label="{t}">{html_escape(text)}</span>'
  return f'<span class="g {color}">{html_escape(text)}</span>'


def page_counts(ahead, behind, ref=""):
  """A count cell of the counts ahead and behind, with an optional ref."""
  cell, color = count_cell(ahead, behind)
  out = ""
  if ref:
    out += f'<span class="ref">{html_escape(ref)}</span> '
  if ahead:
    out += page_glyph(cell, color, f"{ahead} ahead, {behind} behind")
  else:
    out += page_glyph(cell, color)
  return out


def page_tile(value, text, color):
  return f'<div class="tile"><b class="{color}">{value}</b><span>{text}</span></div>'


def page_attention(attention):
  out = "<h2>Needs attention</h2>"
  if not attention:
    return out + f"<p>{page_glyph(G_OK, 'green')} Nothing needs attention.</p>"
  out += '<div class="scroll"><table><tr><th></th><th>Repo</th><th>Branch</th><th>What</th><th>Command</th></tr>'
  for rank in ("1", "2", "3"):
    for a in attention:
      if _v(a, "a_rank") != rank:
        continue
      branch = html_escape(_v(a, "a_branch")) or G_NA
      out += (
        f"<tr><td>{page_glyph(_v(a, 'a_glyph'), _v(a, 'a_color'))}</td><td>{html_escape(_v(a, 'a_repo'))}</td>"
        f'<td class="m">{branch}</td><td>{html_escape(_v(a, "a_msg"))}</td>'
        f'<td class="m">{html_escape(_v(a, "a_cmd"))}</td></tr>'
      )
  return out + "</table></div>"


def page_state(row):
  """The glyphs of the state parts of the row. The word after ": " of a part,
  for example "M2 ??1" of "dirty: M2 ??1", follows its glyph."""
  out = ""
  for glyph, color, word in state_parts(row):
    if not glyph:
      continue
    out += f"{page_glyph(glyph, color, word)} "
    if ": " in word:
      out += f'<span class="ref">{html_escape(word.split(": ", 1)[1])}</span> '
  return out


def page_row(row):
  kind = _v(row, "kind")
  if kind == "main_worktree":
    glyph, title = G_FOLDER, "main worktree"
  elif kind == "worktree":
    glyph, title = G_TREE, "linked worktree"
  else:
    glyph, title = G_BRANCH, "branch without a worktree"
  branch = html_escape(_v(row, "w_branch"))
  if _v(row, "w_detached"):
    branch = f"{page_glyph(G_DETACHED, 'yellow', 'detached')} {branch}"
  if _v(row, "w_default"):
    branch = f"{branch} {page_glyph(G_DEFAULT, 'green', 'default branch (origin/HEAD)')}"
  path = _v(row, "w_path")
  home = os.environ.get("HOME", "")
  if home and path.startswith(home):
    path = "~" + path[len(home) :]
  path = html_escape(path)
  out = (
    f'<tr><td>{page_glyph(glyph, "", title)}</td><td class="m">{branch}</td><td class="m">{_v(row, "w_commit")}</td>'
    f"<td>{_v(row, 'w_age')}</td><td>{page_counts(_v(row, 'w_ba'), _v(row, 'w_bb'), _v(row, 'w_base'))}</td>"
    f"<td>{page_counts(_v(row, 'w_pa'), _v(row, 'w_pb'))}</td><td>"
  )
  origin = _v(row, "w_origin")
  if origin == "gone":
    out += page_glyph(G_GONE, "red", "upstream gone")
  elif origin == "local":
    out += page_glyph(G_LOCAL, "dim", "local only")
  elif origin == "none":
    out += page_glyph(G_NA, "dim", "no upstream")
  else:
    out += page_counts(_v(row, "w_oa"), _v(row, "w_ob"))
  out += "</td><td>"
  if _v(row, "w_sync"):
    out += page_glyph(G_SYNC, "green", "in-sync: has the HEAD of the main worktree")
  else:
    out += page_glyph(G_DRIFT, "red", "drifted: does not have the HEAD of the main worktree")
  merged, color = merged_cell(row)
  title = {"no": "in neither main nor develop", "": "nothing to compare"}.get(
    _v(row, "w_merged"), f"each commit is in {_v(row, 'w_merged').replace('both', 'main and develop')}"
  )
  out += f"</td><td>{page_state(row)}</td><td>{page_glyph(merged, color, title)}</td><td>"
  if _n(row, "w_stash") > 0:
    out += page_glyph(f"{G_STASH}{_v(row, 'w_stash')}", "yellow", "stash")
  else:
    out += page_glyph(G_NA, "dim")
  return out + f'</td><td class="m">{path or G_NA}</td></tr>'


def page_repo_row(row):
  info = f"{_v(row, 'r_role')} {G_NA} {_v(row, 'r_host')}"
  if _v(row, "r_default"):
    info += f" {G_NA} default {_v(row, 'r_default')}"
  if _v(row, "r_pinned"):
    info += f" {G_NA} pinned by {_v(row, 'r_pinned')}"
  if _v(row, "r_fetched"):
    info += f" {G_NA} fetched {_v(row, 'r_fetched')} ago"
  out = (
    f'<tr class="repo"><td colspan="12">{page_glyph(_v(row, "r_glyph"))}{html_escape(_v(row, "repo"))}'
    f'<span class="i">{html_escape(info)}</span></td></tr>'
  )
  note = _v(row, "r_note")
  if note:
    # The first character is upper case (only a-z, as tr of the shell does)
    # and is not escaped, as in the shell version.
    first = note[0].upper() if "a" <= note[0] <= "z" else note[0]
    out += f'<tr><td>{page_glyph(G_FETCH, "yellow", note)}</td><td colspan="11">{first}{html_escape(note[1:])}.'
    if _v(row, "r_fix"):
      out += f" Run <code>{html_escape(_v(row, 'r_fix'))}</code>."
    out += "</td></tr>"
  return out


def legend_color(glyph):
  """The color of a legend glyph, the same as in the table."""
  if glyph in (G_OK, G_SYNC, G_MERGED, G_DEFAULT):
    return "green"
  if glyph in (G_DRIFT, G_WARN, G_OP, G_GONE, G_NOFOLDER):
    return "red"
  if glyph in (G_DOWN, G_DETACHED, "+", "-", G_MIX, G_LOCK, G_STASH, G_PIN, G_UNMERGED, G_FETCH):
    return "yellow"
  if glyph in (G_LOCAL, G_NA):
    return "dim"
  return ""


def page_legend():
  """One card for each section, with one glyph and its text on each line. An
  entry with no section name continues the section before it, in a card of two
  columns."""
  out = '<h2>Legend</h2><div class="legend">'
  for i, entry in enumerate(LEGEND):
    section, _, rest = entry.partition("|")
    has_next = i + 1 < len(LEGEND)
    if section:
      cls = ' class="wide"' if has_next and LEGEND[i + 1].startswith("|") else ""
      out += f"<section{cls}><h3>{html_escape(section)}</h3><ul>"
    for item in rest.split("|"):
      glyph = item.split(" ", 1)[0]
      text = item.split(" ", 1)[1] if " " in item else item
      out += f"<li>{page_glyph(glyph, legend_color(glyph))}<span>{html_escape(text)}</span></li>"
    if not has_next or not LEGEND[i + 1].startswith("|"):
      out += "</ul></section>"
  return out + "</div>"


def _page(rows, attention, now):
  """The HTML text of the page."""
  repos = worktrees = branches = changed = 0
  for row in rows:
    kind = _v(row, "kind")
    if kind == "repo":
      repos += 1
    elif kind == "branch":
      branches += 1
    else:
      worktrees += 1
      if _n(row, "w_dirty") > 0 or _n(row, "w_conflict") > 0:
        changed += 1
  name = html_escape(_v(rows[0] if rows else {}, "repo"))
  out = (
    '<!doctype html><html lang="en"><meta charset="utf-8">'
    '<meta name="viewport" content="width=device-width,initial-scale=1">'
    f"<title>{name} worktrees</title><style>"
    f"@font-face{{font-family:Glyphs;src:url(data:font/woff2;base64,{WORKTREES_FONT}) format('woff2')}}"
    f"{PAGE_STYLES}"
    f'</style><h1>{name} worktrees</h1><p class="sub">Written by <code>mise run git:worktree:list</code> on {now}.'
    '</p><div class="tiles">'
  )
  out += page_tile(repos, "repos", "")
  out += page_tile(worktrees, "worktrees", "")
  out += page_tile(branches, "branches, no worktree", "")
  out += page_tile(changed, "with changes", "yellow")
  out += page_tile(len(attention), "need attention", "red")
  out += "</div>"
  out += page_attention(attention)
  out += (
    '<h2>All repos</h2><div class="scroll"><table><tr><th></th><th>Branch</th><th>Commit</th><th>Age</th>'
    "<th>Base</th><th>Pinned</th><th>Origin</th><th>Sync</th><th>State</th><th>Merged</th><th>Stash</th><th>Path</th></tr>"
  )
  for row in rows:
    out += page_repo_row(row) if _v(row, "kind") == "repo" else page_row(row)
  out += "</table></div>"
  out += page_legend()
  out += "<footer>This page shows the state when the task ran. Run the task again to refresh it.</footer></html>\n"
  return out


def write_worktrees_page(rows, attention, now, folder="/tmp/code-worktrees"):
  """Write the page and print its path; return the path. The folder and the
  page are only for this user, because /tmp is shared and the page has paths
  of the machine. On a failure (for example another user owns the folder) it
  prints nothing and returns None, and the table then has no link.

  rows and attention are lists of dicts (see the top of this file); now is the
  time text that the page shows.
  """
  old = os.umask(0o077)
  try:
    os.makedirs(folder, exist_ok=True)
  except OSError:
    return None
  finally:
    os.umask(old)
  try:
    if os.path.islink(folder) or os.stat(folder).st_uid != os.geteuid():
      return None
  except OSError:
    return None
  first = rows[0] if rows else {}
  file = f"{folder}/{_v(first, 'repo').replace('/', '_')}.html"
  try:
    fd, tmp = tempfile.mkstemp(prefix=".page.", dir=folder)
  except OSError:
    return None
  try:
    with os.fdopen(fd, "w", encoding="utf-8", newline="") as f:
      f.write(_page(rows, attention, now))
    os.replace(tmp, file)
  except OSError:
    try:
      os.unlink(tmp)
    except OSError:
      pass
    return None
  print(file, flush=True)
  return file
